// one of the logo's random Presets, for Preset Generation
namespace aquanode::plugins::phizmo
{
    bool randomPreset (juce::AudioProcessor& p, int style, juce::uint32 seed)
    {
        auto* ph = dynamic_cast<aqp_phizmo::PhizmoAudioProcessor*> (&p);
        juce::String status;
        return ph != nullptr && ph->randomPreset (style, (juce::int64) seed | 1, status);
    }
}

// the logo's random styles (Surprise Me, the any-style one, last), for the
// Random Plugin Preset module; saved as a .phizmo preset
#include "../Host/RandomPresetSources.h"
namespace
{
    const bool phizmoRandomRegistered = aquanode::plugins::randompreset::registerSource ([]
    {
        aquanode::plugins::randompreset::Source s;
        s.pluginId = "phizmo";
        s.name = "Phizmo";
        s.lists = []
        {
            using P = aqp_phizmo::PhizmoAudioProcessor;
            aquanode::plugins::randompreset::Lists l;
            for (int i = 0; i < (int) P::NumRandomStyles; ++i)
                l.kinds.add (P::randomStyleName (i));
            l.defaultKind = (int) P::RandSurprise;
            return l;
        };
        s.roll = [] (juce::AudioProcessor& p, int kind, int, int, juce::uint32 seed) -> juce::String
        {
            auto* ph = dynamic_cast<aqp_phizmo::PhizmoAudioProcessor*> (&p);
            juce::String status;
            if (ph == nullptr || ! ph->randomPreset (kind, (juce::int64) seed | 1, status))
                return {};
            return ph->getCurrentPresetName().isNotEmpty() ? ph->getCurrentPresetName() : status;
        };
        s.presetExtension = "phizmo";
        s.presetData = [] (juce::AudioProcessor& p, const juce::String& name, juce::MemoryBlock& out)
        {
            auto* ph = dynamic_cast<aqp_phizmo::PhizmoAudioProcessor*> (&p);
            if (ph == nullptr)
                return false;
            if (name.isNotEmpty())
                ph->setCurrentPresetName (name);
            return aquanode::plugins::randompreset::viaTempFile ("phizmo", [ph] (const juce::File& f) { return ph->savePreset (f); }, out);
        };
        return s;
    }());
}

#if AQUANODE_TEST_HARNESS
// (test harness) generated tables in both of Sound 1's oscillators
bool aqPhizmoGenerate (juce::AudioProcessor& p, int seed)
{
    auto* ph = dynamic_cast<aqp_phizmo::PhizmoAudioProcessor*> (&p);
    if (ph == nullptr) return false;
    juce::String status;
    return ph->generateRandomWavetable (0, (juce::int64) seed, 64, ph->getCycleSizeParam (0), status, 0)
        && ph->generateRandomWavetable (1, (juce::int64) seed + 1, 64, ph->getCycleSizeParam (1), status, 0);
}
#endif

#if AQUANODE_TEST_HARNESS
// 7.0.0 checks (harness mode "round701")
#include <sstream>
std::string aqPhizmoRound701()
{
    std::ostringstream os;
    auto check = [&os] (bool ok, const juce::String& what) { os << (ok ? "  ok   " : "  FAIL ") << what << "\n"; };
    aqp_phizmo::PhizmoAudioProcessor p;
    p.prepareToPlay (48000.0, 512);
    juce::String st;
    const int idx = ::twremake::indexOf ("Long Gongwave");
    check (idx >= 0 && p.loadBuiltinTranswave (3, idx, st) && p.getNumFrames (3) == 74 && p.getSlotOrigin (3) == 3,
           "Phizmo: built-in Long Gongwave in slot 3, 74 frames (" + st + ")");
    juce::MemoryBlock mb;
    p.getStateInformation (mb);
    aqp_phizmo::PhizmoAudioProcessor q;
    q.setStateInformation (mb.getData(), (int) mb.getSize());
    check (q.isWavetableLoaded (3) && q.getWavetableName (3) == "Long Gongwave" && q.getNumFrames (3) == 74,
           "Phizmo: the state reopens with the built-in rebuilt (" + juce::String ((int) mb.getSize()) + " bytes)");
    int builtins = 0, slots = 0;
    for (int seed = 1; seed <= 24; ++seed)
    {
        aqp_phizmo::PhizmoAudioProcessor r;
        r.prepareToPlay (48000.0, 512);
        juce::String s2;
        r.randomPreset (seed % 8, seed * 7919, s2);
        for (int sl = 0; sl < 8; ++sl)
            if (r.isWavetableLoaded (sl)) { ++slots; if (r.getSlotOrigin (sl) == 3) ++builtins; }
    }
    check (builtins > 0 && builtins < slots, "Phizmo random presets: " + juce::String (builtins) + " of " + juce::String (slots)
           + " tables are built-in transwaves");
    return os.str();
}
#endif
